def eraseOverlapIntervals(intervals: List[List[int]]) -> int:
    n = len(intervals)
    max_non_overlapping = 0
    for i in range(1 << n):
        current_subset = []
        valid = True
        for j in range(n):
            if (i >> j) & 1:
                current_subset.append(intervals[j])
        current_subset.sort(key=lambda x: x[0])
        for k in range(len(current_subset) - 1):
            if current_subset[k][1] > current_subset[k + 1][0]:
                valid = False
                break
        if valid:
            max_non_overlapping = max(max_non_overlapping, len(current_subset))
    return n - max_non_overlapping

